import { getComponentByName } from '../utils/dataLoader.js';

const REACT_BITS_RAW = 'https://raw.githubusercontent.com/davidhdev/react-bits/main';

/**
 * Get demo code and usage examples for a component
 */
export async function getDemo(args) {
  const { 
    componentName, 
    version = 'js-css' 
  } = args;

  try {
    // Find component
    const component = getComponentByName(componentName);
    if (!component) {
      return {
        content: [
          {
            type: 'text',
            text: `Component "${componentName}" not found. Use search-react-bits-components to find available components.`
          }
        ]
      };
    }

    // Fetch demo code
    const demoCode = await fetchDemoCode(componentName, component.category);
    
    // Get usage examples
    const usageExamples = generateUsageExamples(componentName, version, component.category);

    // Format response
    const responseText = formatDemoResponse(
      componentName,
      version,
      component,
      demoCode,
      usageExamples
    );

    return {
      content: [
        {
          type: 'text',
          text: responseText
        }
      ]
    };

  } catch (error) {
    return {
      content: [
        {
          type: 'text',
          text: `Error fetching demo: ${error.message}`
        }
      ],
      isError: true
    };
  }
}

/**
 * Fetch demo code from repository
 */
async function fetchDemoCode(componentName, category) {
  const categoryMap = {
    'animations': 'Animations',
    'text-animations': 'TextAnimations',
    'components': 'Components',
    'backgrounds': 'Backgrounds'
  };

  const categoryDir = categoryMap[category] || 'Components';
  const demoPath = `src/demo/${categoryDir}/${componentName}Demo.jsx`;
  
  try {
    const response = await fetch(`${REACT_BITS_RAW}/${demoPath}`);
    if (!response.ok) {
      // Try alternative naming conventions
      const variations = [
        `src/demo/${categoryDir}/${capitalizeFirst(componentName)}Demo.jsx`,
        `src/demo/${categoryDir}/${componentName.toUpperCase()}Demo.jsx`,
        `src/demo/${categoryDir}/${toPascalCase(componentName)}Demo.jsx`
      ];

      for (const variation of variations) {
        const altResponse = await fetch(`${REACT_BITS_RAW}/${variation}`);
        if (altResponse.ok) {
          return await altResponse.text();
        }
      }

      throw new Error(`Demo file not found for ${componentName}`);
    }
    
    return await response.text();
  } catch (error) {
    return generateDemoPlaceholder(componentName, category);
  }
}

/**
 * Generate usage examples based on component type
 */
function generateUsageExamples(componentName, version, category) {
  const examples = [];

  // Basic usage example
  examples.push({
    title: 'Basic Usage',
    code: generateBasicUsage(componentName, version)
  });

  // Category-specific examples
  switch (category) {
    case 'components':
      examples.push({
        title: 'With Custom Props',
        code: generateComponentExample(componentName, version)
      });
      break;
    
    case 'animations':
      examples.push({
        title: 'Animation Configuration',
        code: generateAnimationExample(componentName, version)
      });
      break;
    
    case 'text-animations':
      examples.push({
        title: 'Text Animation Setup',
        code: generateTextAnimationExample(componentName, version)
      });
      break;
    
    case 'backgrounds':
      examples.push({
        title: 'Background Integration',
        code: generateBackgroundExample(componentName, version)
      });
      break;
  }

  // Responsive example
  if (version.includes('tailwind')) {
    examples.push({
      title: 'Responsive Design',
      code: generateResponsiveExample(componentName)
    });
  }

  return examples;
}

/**
 * Generate basic usage code
 */
function generateBasicUsage(componentName, version) {
  const importPath = version.includes('ts') ? `./${capitalizeFirst(componentName)}.tsx` : `./${capitalizeFirst(componentName)}.jsx`;
  
  return `import React from 'react';
import ${capitalizeFirst(componentName)} from '${importPath}';

export default function App() {
  return (
    <div>
      <${capitalizeFirst(componentName)} />
    </div>
  );
}`;
}

/**
 * Generate component-specific example
 */
function generateComponentExample(componentName, version) {
  const componentExamples = {
    'stack': `<Stack
  items={[
    { id: 1, content: 'Card 1' },
    { id: 2, content: 'Card 2' },
    { id: 3, content: 'Card 3' }
  ]}
  maxVisible={3}
  stackOffset={10}
/>`,
    'dock': `<Dock
  items={[
    { icon: '🏠', label: 'Home' },
    { icon: '📁', label: 'Files' },
    { icon: '⚙️', label: 'Settings' }
  ]}
  size={60}
  magnification={1.5}
/>`,
    'spotlight-card': `<SpotlightCard
  title="Featured Content"
  description="This card has a spotlight effect on hover"
  spotlightColor="#3b82f6"
  className="max-w-md"
/>`
  };

  const example = componentExamples[componentName] || `<${capitalizeFirst(componentName)}
  // Add your custom props here
  className="custom-class"
/>`;

  return `import React from 'react';
import ${capitalizeFirst(componentName)} from './${capitalizeFirst(componentName)}';

export default function Example() {
  return (
    <div className="container">
      ${example}
    </div>
  );
}`;
}

/**
 * Generate animation example
 */
function generateAnimationExample(componentName, version) {
  return `import React from 'react';
import ${capitalizeFirst(componentName)} from './${capitalizeFirst(componentName)}';

export default function AnimationExample() {
  return (
    <${capitalizeFirst(componentName)}
      duration={0.5}
      delay={0.1}
      easing="easeInOut"
      trigger="hover"
    />
  );
}`;
}

/**
 * Generate text animation example
 */
function generateTextAnimationExample(componentName, version) {
  return `import React from 'react';
import ${capitalizeFirst(componentName)} from './${capitalizeFirst(componentName)}';

export default function TextExample() {
  return (
    <${capitalizeFirst(componentName)}
      text="Hello, World!"
      animationType="fadeIn"
      staggerDelay={0.1}
      className="text-4xl font-bold"
    />
  );
}`;
}

/**
 * Generate background example
 */
function generateBackgroundExample(componentName, version) {
  return `import React from 'react';
import ${capitalizeFirst(componentName)} from './${capitalizeFirst(componentName)}';

export default function BackgroundExample() {
  return (
    <div className="relative min-h-screen">
      <${capitalizeFirst(componentName)}
        intensity={0.5}
        color="#3b82f6"
        speed={1}
      />
      <div className="relative z-10">
        <h1>Your content here</h1>
      </div>
    </div>
  );
}`;
}

/**
 * Generate responsive example for Tailwind
 */
function generateResponsiveExample(componentName) {
  return `import React from 'react';
import ${capitalizeFirst(componentName)} from './${capitalizeFirst(componentName)}';

export default function ResponsiveExample() {
  return (
    <${capitalizeFirst(componentName)}
      className="
        w-full 
        sm:w-1/2 
        md:w-1/3 
        lg:w-1/4
        p-4
        sm:p-6
        md:p-8
      "
    />
  );
}`;
}

/**
 * Format demo response
 */
function formatDemoResponse(name, version, component, demoCode, examples) {
  let output = `# ${capitalizeFirst(name)} Demo\n\n`;
  
  output += `**Component:** ${name}\n`;
  output += `**Category:** ${component.category}\n`;
  output += `**Version:** ${version}\n`;
  output += `**Description:** ${component.description}\n\n`;

  // Original demo code
  output += `## Original Demo Code\n\n`;
  output += `\`\`\`jsx\n${demoCode}\n\`\`\`\n\n`;

  // Usage examples
  output += `## Usage Examples\n\n`;
  examples.forEach((example, index) => {
    output += `### ${example.title}\n\n`;
    output += `\`\`\`jsx\n${example.code}\n\`\`\`\n\n`;
  });

  // Tips
  output += `## Tips & Best Practices\n\n`;
  output += `1. **Performance**: Consider using React.memo() for components that re-render frequently\n`;
  output += `2. **Accessibility**: Add appropriate ARIA labels and keyboard navigation support\n`;
  output += `3. **Customization**: Most components accept className props for custom styling\n`;
  
  if (version.includes('tailwind')) {
    output += `4. **Tailwind**: Use Tailwind utilities for responsive design and theming\n`;
  }
  
  if (component.category === 'animations') {
    output += `4. **Animation**: Test animations on different devices for performance\n`;
  }

  output += `\n---\n\n`;
  output += `💡 **Next Steps:**\n`;
  output += `• Use \`get-react-bits-component\` to get the full component code\n`;
  output += `• Use \`get-react-bits-install-guide\` for setup instructions\n`;
  output += `• Customize the component props to match your design needs\n`;

  return output;
}

/**
 * Utility functions
 */
function capitalizeFirst(str) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

function toPascalCase(str) {
  return str.split('-').map(capitalizeFirst).join('');
}

function generateDemoPlaceholder(componentName, category) {
  return `// Demo placeholder for ${capitalizeFirst(componentName)}
import React from 'react';
import ${capitalizeFirst(componentName)} from './${capitalizeFirst(componentName)}';

export default function ${capitalizeFirst(componentName)}Demo() {
  return (
    <div className="demo-container">
      <h2>${capitalizeFirst(componentName)} Demo</h2>
      <p>Category: ${category}</p>
      <${capitalizeFirst(componentName)} />
    </div>
  );
}`;
}
